import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export interface IArgumentExceptionData {
    argumentName: string;
}

export class ArgumentException extends BaseException<IArgumentExceptionData> {
    public static type: string = 'System.ArgumentException';

    constructor(argumentName: string, reason: string = 'No reason specified') {
        super(ArgumentException.type, `Invalid argument: ${argumentName}. ${reason}`, {
            argumentName
        });
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
